import XCTest

final class TapOpenTests: XCTestCase {
    func testTapOpenOnSpringBoardAlert() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let openButton = springboard.buttons["Open"]
        guard openButton.waitForExistence(timeout: 15) else {
            XCTFail("Open button not found")
            return
        }
        openButton.tap()
        Thread.sleep(forTimeInterval: 2)
    }
}

import XCTest

final class TapOpenTests: XCTestCase {
    func testTapOpenOnSpringBoardAlert() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        for _ in 0..<4 {
            let openButton = springboard.buttons["Open"]
            guard openButton.waitForExistence(timeout: 10) else {
                break
            }
            openButton.tap()
            Thread.sleep(forTimeInterval: 4)
        }
    }
}
